.ds .ds-token-gradients i { width:var(--p-control-size-lg); height:var(--p-control-size-lg); border-radius:var(--p-inner-radius); border:var(--p-border-width) solid var(--p-line); background:var(--p-gradient-sheen); }
.ds .ds-token-gradients [data-token="backdrop"] { background:var(--p-gradient-backdrop); }
.ds .ds-token-gradients [data-token="rule"] { border-color:transparent; background:var(--p-gradient-rule) 0 50%/100% var(--p-border-width-strong) no-repeat; }
